<div class="ui container"><div class="ui raised segment"><h2 class="ui header"><i class="landmark blue icon"></i><div class="content">Kop Surat Resmi<div class="sub header">Identitas default mengikuti OPD pengguna dan dapat diganti dengan gambar kop penuh.</div></div></h2><form class="ui form" id="officialLetterheadForm" enctype="multipart/form-data"><input type="hidden" name="id" value="<?= (int)($kop['id']??0) ?>"><div class="two fields"><div class="required field"><label>Nama Pemerintah</label><input name="nama_pemerintah" value="<?= htmlspecialchars($kop['nama_pemerintah']??'') ?>"></div><div class="required field"><label>Nama OPD</label><input name="nama_opd" value="<?= htmlspecialchars($kop['nama_opd']??'') ?>"></div></div><div class="field"><label>Alamat</label><textarea name="alamat" rows="2"><?= htmlspecialchars($kop['alamat']??'') ?></textarea></div><div class="four fields"><div class="field"><label>Telepon</label><input name="telepon" value="<?= htmlspecialchars($kop['telepon']??'') ?>"></div><div class="field"><label>Email</label><input type="email" name="email" value="<?= htmlspecialchars($kop['email']??'') ?>"></div><div class="field"><label>Website</label><input name="website" value="<?= htmlspecialchars($kop['website']??'') ?>"></div><div class="field"><label>Kode Pos</label><input name="kode_pos" value="<?= htmlspecialchars($kop['kode_pos']??'') ?>"></div></div><div class="three fields"><div class="field"><label>Logo Kiri</label><input type="file" name="logo_kiri" accept="image/png,image/jpeg,image/webp"></div><div class="field"><label>Logo Kanan</label><input type="file" name="logo_kanan" accept="image/png,image/jpeg,image/webp"></div><div class="field"><label>Gambar Kop Penuh</label><input type="file" name="gambar_kop" accept="image/png,image/jpeg,image/webp"></div></div><div class="two fields"><div class="field"><div class="ui toggle checkbox"><input type="checkbox" name="gunakan_gambar_kop" value="1" <?= !empty($kop['gunakan_gambar_kop'])?'checked':'' ?>><label>Gunakan gambar kop penuh</label></div></div><div class="field"><div class="ui toggle checkbox"><input type="checkbox" name="aktif" value="1" <?= !isset($kop['aktif'])||!empty($kop['aktif'])?'checked':'' ?>><label>Jadikan kop aktif</label></div></div></div><button class="ui primary button" type="submit"><i class="save icon"></i>Simpan Kop</button></form></div></div><script>$(function(){$('.ui.checkbox').checkbox();$('#officialLetterheadForm').off('submit').on('submit',function(e){e.preventDefault();const b=$(this).find('button').addClass('loading disabled');window.Ajax.request({url:'/kop_surat/save',method:'POST',data:new FormData(this),processData:false,contentType:false,success:()=>location.reload(),complete:()=>b.removeClass('loading disabled')});});});</script>
